mapper.select:
SELECT COUNT(*) FROM (
    SELECT pt.project_id
    FROM label_project_team pt
    JOIN label_project p ON p.id = pt.project_id AND p.deleted = 0
    WHERE pt.deleted = 0 AND pt.team_id = #{teamId}
    UNION
    SELECT id AS project_id
    FROM label_project
    WHERE deleted = 0 AND team_id = #{teamId}
) bound

mapper.update:
UPDATE label_team
SET deleted = 1, updated_by = #{userId}, update_time = NOW()
WHERE id = #{id}
